import { NextRequest, NextResponse } from 'next/server';
import { getQuoteByToken, updateLineItems, findQuoteByToken, updateQuote, type UpdateLineItemsRequest } from '@/lib/airtable';

export const dynamic = 'force-dynamic';

// GET /api/quotes/[token]
export async function GET(
  _request: NextRequest,
  { params }: { params: { token: string } }
) {
  try {
    const { token } = params;

    if (!token) {
      return NextResponse.json(
        { error: 'Token is required' },
        { status: 400 }
      );
    }

    const result = await getQuoteByToken(token);

    // Include quoteRequest field for backward compatibility
    return NextResponse.json({
      ...result,
      quoteRequest: result.quote // Legacy field name
    });
  } catch (error: any) {
    const status = error?.status || 500;
    const message = error?.message || 'Failed to fetch quote';

    return NextResponse.json(
      { error: message },
      { status }
    );
  }
}

// PUT /api/quotes/[token]
export async function PUT(
  request: NextRequest,
  { params }: { params: { token: string } }
) {
  try {
    const { token } = params;
    const body: UpdateLineItemsRequest = await request.json();

    const response: any = { ok: true };

    // Update line items if provided
    if (body.lineItems && body.lineItems.length > 0) {
      const updatedLineItems = await updateLineItems(body.lineItems);
      response.lineItems = updatedLineItems;
    }

    // Find the quote to update selected services
    const quote = await findQuoteByToken(token);
    if (!quote) {
      return NextResponse.json(
        { error: 'Quote not found' },
        { status: 404 }
      );
    }

    // Build selected services from line items if not explicitly provided
    let selectedServices = body.selectedServices;
    if (!selectedServices && body.lineItems) {
      selectedServices = body.lineItems
        .filter(item => item.chosenFrequency && item.chosenFrequency > 0)
        .map(item => {
          // Find the service name from the line items
          // This would need to be passed in the request or fetched
          return ''; // Placeholder - needs service name
        })
        .filter(Boolean);
    }

    // Update quote if we have fields to update
    if (selectedServices) {
      const updatedQuote = await updateQuote(quote.id, { selectedServices });
      response.quote = updatedQuote;
    }

    return NextResponse.json(response);
  } catch (error: any) {
    const message = error?.message || 'Failed to update quote';

    return NextResponse.json(
      { error: message },
      { status: 500 }
    );
  }
}

/**
 * Airtable module - Public API
 * 
 * This is the main entry point for all Airtable-related functionality.
 * Other parts of the application should import from '@/lib/airtable'
 */

// Export all types
export type {
  // Domain models
  Quote,
  LineItem,
  QuoteWithLineItems,

  // API types
  QuoteResponse,
  UpdateLineItemsRequest,
  UpdateLineItemsResponse,

  // Component props
  LineItemTableProps,

  // Airtable-specific types (if needed externally)
  AirtableQuoteFields,
  AirtableLineItemFields,
  AirtableQuoteRecord,
  AirtableLineItemRecord
} from './types';

// Export client functions
export {
  getQuoteByToken,
  updateLineItems,
  updateQuote,
  findQuoteByToken
} from './client';

// Export configuration (if needed externally)
export { AIRTABLE_CONFIG } from './config';

// Export mapper functions (if needed externally)
export {
  mapAirtableToQuote,
  mapQuoteToAirtable,
  mapAirtableToLineItem,
  mapLineItemToAirtable,
  mapAirtableToLineItems,
  prepareLineItemUpdates
} from './mappers';

