import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import LineItemsTable from '@/app/components/LineItemsTable';
import QuoteViewerPage from '@/app/q/[token]/page';
import { NextRequest, NextResponse } from 'next/server';
import { DELETE } from '@/app/api/quotes/[token]/route';

// Mock the toast hook
const mockToast = jest.fn();
jest.mock('@/components/ui/use-toast', () => ({
  useToast: () => ({ toast: mockToast })
}));

// Mock the Airtable functions
jest.mock('@/lib/airtable', () => ({
  deleteLineItem: jest.fn(),
  getQuoteByToken: jest.fn(),
  updateLineItems: jest.fn(),
  findQuoteByToken: jest.fn(),
  updateQuote: jest.fn()
}));

// Mock useParams
jest.mock('next/navigation', () => ({
  ...jest.requireActual('next/navigation'),
  useParams: () => ({ token: 'test-token' }),
  useSearchParams: () => new URLSearchParams()
}));

describe('Delete Line Item Functionality', () => {
  const mockLineItems = [
    {
      id: 'item1',
      service: 'Lawn Mowing',
      chosenFrequency: 2,
      alaCarteRate: 100,
      handldRate: 70
    },
    {
      id: 'item2', 
      service: 'Tree Trimming',
      chosenFrequency: 1,
      alaCarteRate: 200,
      handldRate: 140
    }
  ];

  const mockQuote = {
    id: 'quote1',
    quoteId: 'Q123',
    firstName: 'John',
    lastName: 'Doe',
    email: 'john@example.com',
    city: 'Austin',
    token: 'test-token'
  };

  beforeEach(() => {
    jest.clearAllMocks();
    mockToast.mockClear();
    global.fetch = jest.fn();
  });

  describe('LineItemsTable Component', () => {
    it('should call onRemoveItem when remove button is clicked', () => {
      const mockOnRemoveItem = jest.fn();

      render(
        <LineItemsTable
          lineItems={mockLineItems}
          onRemoveItem={mockOnRemoveItem}
        />
      );

      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      expect(mockOnRemoveItem).toHaveBeenCalledWith('item1');
    });

    it('should disable row when item is in loading state', () => {
      const loadingItems = new Set(['item1']);

      render(
        <LineItemsTable
          lineItems={mockLineItems}
          loadingItems={loadingItems}
          onRemoveItem={jest.fn()}
        />
      );

      const removeButtons = screen.getAllByText('Remove');
      expect(removeButtons[0]).toBeDisabled();
      expect(removeButtons[1]).not.toBeDisabled();
    });

    it('should show loading spinner for items being deleted', () => {
      const loadingItems = new Set(['item1']);

      render(
        <LineItemsTable
          lineItems={mockLineItems}
          loadingItems={loadingItems}
          onRemoveItem={jest.fn()}
        />
      );

      // Check for loading state (opacity change)
      const rows = screen.getByText('Lawn Mowing').closest('div.p-4');
      expect(rows).toHaveClass('opacity-60');
    });
  });

  describe('Delete API Endpoint', () => {
    it('should delete item and return updated data', async () => {
      const { deleteLineItem, getQuoteByToken } = require('@/lib/airtable');

      deleteLineItem.mockResolvedValue(undefined);
      getQuoteByToken.mockResolvedValue({
        quote: mockQuote,
        lineItems: [mockLineItems[1]] // Only second item remains
      });

      const request = new NextRequest('http://localhost:3000/api/quotes/test-token', {
        method: 'DELETE',
        body: JSON.stringify({ itemId: 'item1' })
      });

      const response = await DELETE(request, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(deleteLineItem).toHaveBeenCalledWith('item1');
      expect(getQuoteByToken).toHaveBeenCalledWith('test-token');
      expect(data.ok).toBe(true);
      expect(data.lineItems).toHaveLength(1);
      expect(data.lineItems[0].id).toBe('item2');
    });

    it('should return error when itemId is missing', async () => {
      const request = new NextRequest('http://localhost:3000/api/quotes/test-token', {
        method: 'DELETE',
        body: JSON.stringify({})
      });

      const response = await DELETE(request, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(response.status).toBe(400);
      expect(data.error).toBe('Item ID is required');
    });

    it('should handle deletion errors', async () => {
      const { deleteLineItem } = require('@/lib/airtable');

      deleteLineItem.mockRejectedValue(new Error('Deletion failed'));

      const request = new NextRequest('http://localhost:3000/api/quotes/test-token', {
        method: 'DELETE',
        body: JSON.stringify({ itemId: 'item1' })
      });

      const response = await DELETE(request, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(response.status).toBe(500);
      expect(data.error).toBe('Deletion failed');
    });
  });

  describe('Quote Viewer Page Integration', () => {
    beforeEach(() => {
      global.fetch = jest.fn()
        .mockResolvedValueOnce({
          ok: true,
          json: async () => ({
            quote: mockQuote,
            lineItems: mockLineItems
          })
        });
    });

    it('should handle successful deletion with toast notification', async () => {
      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Mock successful deletion
      global.fetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          ok: true,
          quote: mockQuote,
          lineItems: [mockLineItems[1]] // Only second item remains
        })
      });

      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      await waitFor(() => {
        expect(mockToast).toHaveBeenCalledWith({
          title: "Success",
          description: "Lawn Mowing removed successfully",
          variant: "success"
        });
      });

      // Verify the item is removed from UI
      await waitFor(() => {
        expect(screen.queryByText('Lawn Mowing')).not.toBeInTheDocument();
        expect(screen.getByText('Tree Trimming')).toBeInTheDocument();
      });
    });

    it('should handle deletion failure and revert UI', async () => {
      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Mock failed deletion
      global.fetch.mockResolvedValueOnce({
        ok: false,
        status: 500
      });

      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      await waitFor(() => {
        expect(mockToast).toHaveBeenCalledWith({
          title: "Error",
          description: "Failed to remove Lawn Mowing. Please try again.",
          variant: "destructive"
        });
      });

      // Verify the item is still in the UI
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      expect(screen.getByText('Tree Trimming')).toBeInTheDocument();
    });

    it('should show loading state during deletion', async () => {
      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Mock a delayed response
      let resolvePromise;
      const delayedPromise = new Promise((resolve) => {
        resolvePromise = resolve;
      });

      global.fetch.mockReturnValueOnce(delayedPromise);

      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      // Check that the button is disabled during loading
      await waitFor(() => {
        expect(removeButtons[0]).toBeDisabled();
      });

      // Resolve the promise
      resolvePromise({
        ok: true,
        json: async () => ({
          ok: true,
          quote: mockQuote,
          lineItems: [mockLineItems[1]]
        })
      });

      // Wait for loading to complete
      await waitFor(() => {
        expect(removeButtons[0]).not.toBeDisabled();
      }, { timeout: 3000 });
    });

    it('should handle network errors gracefully', async () => {
      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Mock network error
      global.fetch.mockRejectedValueOnce(new Error('Network error'));

      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      await waitFor(() => {
        expect(mockToast).toHaveBeenCalledWith({
          title: "Error",
          description: "Failed to remove Lawn Mowing. Please try again.",
          variant: "destructive"
        });
      });

      // Verify items are still present
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      expect(screen.getByText('Tree Trimming')).toBeInTheDocument();
    });
  });

  describe('Optimistic Updates', () => {
    it('should optimistically remove item from UI immediately', async () => {
      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Mock a slow response
      const slowPromise = new Promise((resolve) => {
        setTimeout(() => {
          resolve({
            ok: true,
            json: async () => ({
              ok: true,
              quote: mockQuote,
              lineItems: [mockLineItems[1]]
            })
          });
        }, 100);
      });

      global.fetch.mockReturnValueOnce(slowPromise);

      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      // Item should be removed immediately (optimistic update)
      await waitFor(() => {
        expect(screen.queryByText('Lawn Mowing')).not.toBeInTheDocument();
      }, { timeout: 50 });
    });
  });
});

