      id: 'item1',
      service: 'Lawn Mowing',
      chosenFrequency: 2,
      alaCarteRate: 100,
      handldRate: 70
    },
    {
      id: 'item2', 
      service: 'Tree Trimming',
      chosenFrequency: 1,
      alaCarteRate: 200,
      handldRate: 140
    }
  ];

  const mockQuote = {
    id: 'quote1',
    quoteId: 'Q123',
    firstName: 'John',
    lastName: 'Doe',
    email: 'john@example.com',
    city: 'Austin',
    token: 'test-token'
