// app/q/[token]/page.tsx
'use client';

import { useEffect, useMemo, useState } from 'react';
import { useParams, useSearchParams } from 'next/navigation';
import LineItemsTable from '../../components/LineItemsTable';
import type { Quote, LineItem } from '@/lib/airtable';
import { useToast } from '@/components/ui/use-toast';
import { ConfirmationDialog } from '@/components/ui/confirmation-dialog';

const fmtMoney = (n: number | undefined): string =>
  typeof n === 'number' && !Number.isNaN(n)
    ? n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })
    : '-';

interface QuoteData {
  quote: Quote;
  lineItems: LineItem[];
}

/**
 * Resilient READ fetch:
 * - Try NEXT_PUBLIC_API_BASE (if present) and the viewer origin
 * - For each base, try common endpoint shapes
 * - Return the first JSON that succeeds
 */
async function fetchQuoteResilient(token: string): Promise<{ data: QuoteData; okUrl: string }> {
  const origin = typeof window !== 'undefined' ? window.location.origin : '';
  const envBase = (process.env.NEXT_PUBLIC_API_BASE || '').replace(/\/$/, '');
  const bases = [envBase, origin].filter(Boolean);

  const tried: string[] = [];
  for (const base of bases) {
    const urls = [
      `${base}/api/quote/${token}`,
      `${base}/api/quotes/${token}`,
      `${base}/api/quote?token=${encodeURIComponent(token)}`,
    ];
    for (const url of urls) {
      tried.push(url);
      try {
        const res = await fetch(url, { cache: 'no-store' });
        if (!res.ok) continue;
        const data = await res.json();
        // Basic sanity check - a quote payload usually has these fields
        if (data && (Array.isArray(data.lineItems) || data.quote)) {
          return { data, okUrl: url };
        }
      } catch {
        // move on to the next candidate
      }
    }
  }

  // If everything failed, show the URLs we tried to make troubleshooting easy
  throw new Error(`Failed to fetch quote. Tried:\n- ${tried.join('\n- ')}`);
}

function fmtPossessive(name: string | undefined): string {
  if (!name) return 'Your';
  return /s$/i.test(name) ? `${name}'` : `${name}'s`;
}

export default function QuoteViewerPage() {
  const params = useParams();
  const search = useSearchParams();
  const token = params?.token as string;
  const debug = search?.get('debug') === '1';

  const [loading, setLoading] = useState(true);
  const [quoteData, setQuoteData] = useState<QuoteData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loadingItems, setLoadingItems] = useState<Set<string>>(new Set());
  const [deleteConfirmation, setDeleteConfirmation] = useState<{ 
    isOpen: boolean; 
    itemId: string; 
    serviceName: string 
  }>({ isOpen: false, itemId: '', serviceName: '' });
  const { toast } = useToast();

  // Calculate savings client-side from line items with chosen frequencies
  const savings = useMemo(() => {
    if (!quoteData?.lineItems) return 0;
    const selectedItems = quoteData.lineItems.filter(item => item.chosenFrequency && item.chosenFrequency > 0);
    const standardTotal = selectedItems.reduce((sum, item) => sum + (item.alaCarteRate * (item.chosenFrequency || 0)), 0);
    const memberTotal = selectedItems.reduce((sum, item) => sum + (item.handldRate * (item.chosenFrequency || 0)), 0);
    return standardTotal - memberTotal;
  }, [quoteData?.lineItems]);

  useEffect(() => {
    let mounted = true;
    (async () => {
      setLoading(true);
      setError(null);
      try {
        if (!token) throw new Error('Missing token in URL.');
        const { data } = await fetchQuoteResilient(token);
        if (!mounted) return;
        setQuoteData(data);
      } catch (e: any) {
        if (mounted) setError(e?.message || 'Failed to load quote');
      } finally {
        if (mounted) setLoading(false);
      }
    })();
    return () => {
      mounted = false;
    };
  }, [token]);

  const handleFrequencyChange = async (itemId: string, frequency: number) => {
    if (!quoteData) return;

    // Store the original frequency for rollback
    const originalItem = quoteData.lineItems.find(item => item.id === itemId);
    const originalFrequency = originalItem?.chosenFrequency;

    // Add item to loading state
    setLoadingItems(prev => new Set(prev).add(itemId));

    try {
      // Optimistically update the UI
      const updatedLineItems = quoteData.lineItems.map(item => 
        item.id === itemId ? { ...item, chosenFrequency: frequency } : item
      );
      setQuoteData({ ...quoteData, lineItems: updatedLineItems });

      const response = await fetch(`/api/quotes/${token}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          lineItems: [{ id: itemId, chosenFrequency: frequency }]
        })
      });

      if (response.ok) {
        // Success toast
        toast({
          title: "Success",
          description: "Frequency updated successfully",
        });
      } else {
        throw new Error('Failed to update frequency');
      }
    } catch (error) {
      console.error('Failed to update frequency:', error);

      // Revert only the failed item to its original frequency
      const revertedLineItems = quoteData.lineItems.map(item => 
        item.id === itemId ? { ...item, chosenFrequency: originalFrequency } : item
      );
      setQuoteData({ ...quoteData, lineItems: revertedLineItems });

      // Error toast
      toast({
        title: "Error",
        description: "Failed to update frequency. Please try again.",
        variant: "destructive",
      });
    } finally {
      // Remove item from loading state
      setLoadingItems(prev => {
        const newSet = new Set(prev);
        newSet.delete(itemId);
        return newSet;
      });
    }
  };

  const handleDeleteItem = (itemId: string) => {
    if (!quoteData) return;

    const itemToDelete = quoteData.lineItems.find(item => item.id === itemId);
    const serviceName = itemToDelete?.service || 'Service';

    // Show confirmation dialog
    setDeleteConfirmation({
      isOpen: true,
      itemId,
      serviceName
    });
  };

  const confirmDelete = async () => {
    if (!quoteData) return;

    const { itemId, serviceName } = deleteConfirmation;

    // Close the confirmation dialog
    setDeleteConfirmation({ isOpen: false, itemId: '', serviceName: '' });

    // Store the original line items for rollback
    const originalLineItems = [...quoteData.lineItems];

    // Add item to loading state
    setLoadingItems(prev => new Set(prev).add(itemId));

    try {
      // Optimistically remove the item from UI
      const updatedLineItems = quoteData.lineItems.filter(item => item.id !== itemId);
      setQuoteData({ ...quoteData, lineItems: updatedLineItems });

      const response = await fetch(`/api/quotes/${token}`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ itemId })
      });

      if (response.ok) {
        const data = await response.json();
        // Update with the fresh data from server
        setQuoteData({ quote: data.quote, lineItems: data.lineItems });

        // Success toast
        toast({
          title: "Success",
          description: `${serviceName} removed successfully`,
        });
      } else {
        throw new Error('Failed to delete item');
      }
    } catch (error) {
      console.error('Failed to delete item:', error);

      // Revert to original line items
      setQuoteData({ ...quoteData, lineItems: originalLineItems });

      // Error toast
      toast({
        title: "Error",
        description: `Failed to remove ${serviceName}. Please try again.`,
        variant: "destructive",
      });
    } finally {
      // Remove item from loading state
      setLoadingItems(prev => {
        const newSet = new Set(prev);
        newSet.delete(itemId);
        return newSet;
      });
    }
  };

  if (loading) {
    return <main className="p-6">Loading…</main>;
  }
  if (error) {
    return (
      <main className="p-6">
        <pre className="whitespace-pre-wrap rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">
          {error}
        </pre>
      </main>
    );
  }
  if (!quoteData) {
    return <main className="p-6">No quote found.</main>;
  }

  const { quote, lineItems } = quoteData;
  const pageTitle = `${fmtPossessive(quote.firstName)} Handld Quote`;

  return (
    <main className="mx-auto max-w-4xl px-6 py-8 text-brand-navy">
      {/* Header with Logo */}
      <header className="mb-4">
        <div className="flex items-start gap-4 mb-4">
          {/* Logo */}
          <div className="flex-shrink-0">
            <img 
              src="/logo.png" 
              alt="Handld" 
              className="w-16 h-16 object-contain"
            />
          </div>

          {/* Quote Title */}
          <div className="flex-1">
            <h1 className="text-3xl font-bold mb-1 text-brand-navy">
              {pageTitle}
            </h1>
            {quote.quoteId && (
              <div className="text-sm text-brand-navy">
                Quote ID: {quote.quoteId}
              </div>
            )}
          </div>
        </div>
      </header>


      {/* Customer Information - Condensed */}
      <section className="mb-4">
        <div className="border border-gray-200 rounded-xl p-3 bg-brand-light-cream">
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {quote.firstName && quote.lastName && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">Name</div>
                <div className="text-base font-medium text-brand-navy">
                  {quote.firstName} {quote.lastName}
                </div>
              </div>
            )}

            {quote.email && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">Email</div>
                <div className="text-base text-brand-navy">
                  {quote.email}
                </div>
              </div>
            )}

            {quote.city && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">City</div>
                <div className="text-base text-brand-navy">
                  {quote.city}
                </div>
              </div>
            )}

            {quote.stories && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">Stories</div>
                <div className="text-base text-brand-navy">
                  {quote.stories}
                </div>
              </div>
            )}

            {quote.squareFootage && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">Square Footage</div>
                <div className="text-base text-brand-navy">
                  {quote.squareFootage}
                </div>
              </div>
            )}

            {quote.lotSize && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600">Lot Size</div>
                <div className="text-base text-brand-navy">
                  {quote.lotSize}
                </div>
              </div>
            )}
          </div>
        </div>
      </section>


      {/* Services */}
      <section className="mb-4">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-2xl font-bold text-brand-navy">Services</h2>
          <button
            onClick={() => {
              alert('TODO: Add new service to quote');
            }}
            className="text-sm px-4 py-2 rounded-full border border-brand-navy text-brand-navy bg-brand-light-cream hover:bg-brand-cream"
          >
            + Add Service
          </button>
        </div>
        <LineItemsTable 
          lineItems={lineItems}
          loadingItems={loadingItems} 
          onFrequencyChange={handleFrequencyChange}
          onRemoveItem={handleDeleteItem}
        />
      </section>

      {/* Buttons */}
      <section className="space-y-4">
        {/* Savings Highlight - Only show if there are savings */}
        {savings > 0 && (
          <div className="relative">
            <div className="absolute -top-3 left-1/2 transform -translate-x-1/2 bg-green-500 text-white px-4 py-1 rounded-full text-sm font-bold shadow-lg">
              💰 SAVE {fmtMoney(savings)}!
            </div>
            <div className="border-2 border-green-400 bg-gradient-to-r from-green-50 to-emerald-50 rounded-2xl p-4 text-center">
              <div className="text-green-700 font-semibold mb-2">
                🎉 Your Handld Member Savings
              </div>
              <div className="text-3xl font-bold text-green-600 mb-2">
                {fmtMoney(savings)}
              </div>
              <div className="text-sm text-green-600">
                Lock in these savings with Handld Membership!
              </div>
            </div>
          </div>
        )}

        <div className="flex flex-col sm:flex-row gap-4">
          <button
            className="flex-1 rounded-full py-4 px-8 text-lg font-semibold text-white bg-brand-navy hover:bg-opacity-90 transition-all duration-200 shadow-lg"
          >
            {savings > 0 ? `Book Handld Membership — Save ${fmtMoney(savings)}` : 'Book Handld Membership — Save 30%'}
          </button>
          <button
            className="flex-1 rounded-full py-4 px-8 text-lg font-medium border-2 border-brand-navy text-brand-navy bg-brand-light-cream hover:bg-brand-cream transition-all duration-200"
          >
            Book with Standard Pricing
          </button>
        </div>
      </section>

      {debug && (
        <section className="mt-8 p-4 bg-gray-100 rounded-lg">
          <h3 className="font-bold mb-2">Debug Info</h3>
          <pre className="text-xs overflow-auto">
            {JSON.stringify({ quote, lineItems }, null, 2)}
          </pre>
        </section>
      )}

      {/* Confirmation Dialog */}
      <ConfirmationDialog
        isOpen={deleteConfirmation.isOpen}
        title="Remove Service"
        message={`Are you sure you want to remove "${deleteConfirmation.serviceName}" from your quote? This action cannot be undone.`}
        confirmLabel="Remove"
        cancelLabel="Cancel"
        variant="danger"
        onConfirm={confirmDelete}
        onCancel={() => setDeleteConfirmation({ isOpen: false, itemId: '', serviceName: '' })}
      />
    </main>
  );
}

